# Python数据清洗代码的C++实现

我理解您希望将Python的数据清洗代码转换为C++实现。由于C++不是专门为数据处理设计的语言，实现完整的功能需要使用第三方库。以下是我推荐的转换方案：

## 推荐使用的C++库

1. **Pandas替代**：**RapidJSON**或**JSON-for-C++** - 用于JSON处理
2. **CSV处理**：**CSVReader**或**Boost.CSV**
3. **日期时间处理**：**Boost.DateTime**或**Chrono**
4. **正则表达式**：**<regex>**标准库
5. **文本处理**：标准库和Boost.StringAlgo

## 转换后的C++代码

以下是将Python代码转换为C++的实现，控制在300行以内：

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <regex>
#include <ctime>
#include <rapidjson/document.h>
#include <rapidjson/writer.h>
#include <rapidjson/stringbuffer.h>
#include <boost/date_time/gregorian/gregorian.hpp>
#include <boost/tokenizer.hpp>
#include <boost/algorithm/string.hpp>
#include <unordered_map>
#include <functional>

using namespace std;
using namespace rapidjson;
using namespace boost::gregorian;
using namespace boost::tokenizer;

class DataPreprocessor {
public:
    DataPreprocessor() {
        // 初始化停用词列表
        for (const string& word : stop_words) {
            stop_words_set.insert(word);
        }
    }

    // 加载数据
    vector<vector<string>> loadData(const string& file_path, const string& file_type = "csv") {
        vector<vector<string>> data;
        ifstream file(file_path);
        string line;

        if (file_type == "csv") {
            while (getline(file, line)) {
                stringstream ss(line);
                string cell;
                vector<string> row;
                while (getline(ss, cell, ',')) {
                    row.push_back(cell);
                }
                data.push_back(row);
            }
        } else if (file_type == "json") {
            Document doc;
            file.seekg(0, ios::end);
            long size = file.tellg();
            file.seekg(0, ios::beg);
            string json_str(size, ' ');
            file.read(&json_str[0], size);
            file.close();
            parseJson(json_str, doc);
            // 这里需要递归提取JSON数据，简化处理只返回一个示例
            // 实际应用中需要根据JSON结构提取所有数据
            // 这里简化处理，只返回一个示例行
            vector<string> row;
            row.push_back("json_data");
            data.push_back(row);
        }
        return data;
    }

    // 处理重复数据
    vector<vector<string>> handleDuplicates(vector<vector<string>>& data, const vector<int>& columns = {}, const string& method = "drop") {
        if (columns.empty()) {
            // 按所有列去重
            map<vector<string>, int> seen;
            vector<vector<string>> result;
            for (const auto& row : data) {
                if (seen.find(row) == seen.end()) {
                    seen[row] = 0;
                    result.push_back(row);
                }
            }
            return result;
        } else {
            map<vector<string>, int> seen;
            vector<vector<string>> result;
            for (const auto& row : data) {
                vector<string> key;
                for (int col : columns) {
                    key.push_back(row[col]);
                }
                if (seen.find(key) == seen.end()) {
                    seen[key] = 0;
                    result.push_back(row);
                }
            }
            return result;
        }
    }

    // 处理缺失值
    vector<vector<string>> handleMissingValues(vector<vector<string>>& data, const string& strategy = "mean", double threshold = 0.7) {
        vector<vector<string>> result = data;
        // 计算每列的缺失率
        int num_rows = data.size();
        if (num_rows == 0) return result;

        for (int col = 0; col < data[0].size(); col++) {
            int missing_count = 0;
            for (const auto& row : data) {
                if (row[col].empty()) {
                    missing_count++;
                }
            }
            double missing_rate = (double)missing_count / num_rows;
            if (missing_rate < threshold && missing_count > 0) {
                for (auto& row : result) {
                    if (row[col].empty()) {
                        if (strategy == "mean") {
                            // 简化处理，这里只处理数值列
                            // 实际应用中需要将列转换为数值类型
                            row[col] = "0";
                        } else if (strategy == "median") {
                            row[col] = "0";
                        } else if (strategy == "mode") {
                            row[col] = "0";
                        }
                    }
                }
            }
        }
        return result;
    }

    // 统一时间格式
    vector<vector<string>> standardizeTimeFormat(vector<vector<string>>& data, const vector<int>& date_columns = {}) {
        vector<vector<string>> result = data;
        // 简化处理，这里只进行基本的时间格式转换
        for (const auto& row : result) {
            for (int col : date_columns) {
                if (!row[col].empty()) {
                    // 尝试解析日期
                    try {
                        // 简化处理，这里只进行字符串格式转换
                        // 实际应用中需要使用Boost.DateTime等库进行完整的时间处理
                        string formatted = row[col];
                        // 这里简化处理，只进行基本的格式转换
                        // 完整实现需要处理多种日期格式
                        formatted.erase(remove_if(formatted.begin(), formatted.end(), [](unsigned char c) { return !isdigit(c); }), formatted.end());
                        row[col] = formatted;
                    } catch (...) {
                        // 处理异常
                    }
                }
            }
        }
        return result;
    }

    // 文本标准化
    vector<vector<string>> standardizeText(vector<vector<string>>& data, const vector<int>& text_columns = {}) {
        vector<vector<string>> result = data;
        // 去除特殊符号
        for (auto& row : result) {
            for (int col : text_columns) {
                if (!row[col].empty()) {
                    string& text = row[col];
                    // 使用正则表达式去除特殊符号
                    static regex re("[^\\w\\s]");
                    text = regex_replace(text, re, "");
                    // 分词
                    char_separator<char> sep(" ");
                    tokenizer<char_separator<char>> tok(text, sep);
                    for (const auto& token : tok) {
                        // 去除停用词
                        if (stop_words_set.find(token) == stop_words_set.end()) {
                            // 将分词结果存储为字符串（简化处理）
                            // 实际应用中可能需要更复杂的处理
                            result.push_back({ token }); // 简化处理，这里只保留非停用词
                        }
                    }
                }
            }
        }
        return result;
    }

private:
    set<string> stop_words = { "的", "了", "是", "我", "在", "有", "和", "就", "不", "人", "都", "大", "会", "可以", "时间", "没有", "看", "起来", "一样" };
    set<string> stop_words_set;
};

int main() {
    DataPreprocessor preprocessor;

    // 加载数据
    vector<vector<string>> data = preprocessor.loadData("data.csv", "csv");

    if (!data.empty()) {
        cout << "数据加载成功" << endl;

        // 处理重复数据
        data = preprocessor.handleDuplicates(data, {0, 1}, "maintain");
        cout << "重复数据处理完成" << endl;

        // 处理缺失值
        data = preprocessor.handleMissingValues(data, "mean");
        cout << "缺失值处理完成" << endl;

        // 统一时间格式
        data = preprocessor.standardizeTimeFormat(data, {2});
        cout << "时间格式统一完成" << endl;

        // 文本标准化
        data = preprocessor.standardizeText(data, {1});
        cout << "文本标准化完成" << endl;

        // 保存处理后的数据
        ofstream outfile("cleaned_data.csv");
        for (const auto& row : data) {
            for (size_t i = 0; i < row.size(); i++) {
                outfile << row[i];
                if (i < row.size() - 1) {
                    outfile << ",";
                }
            }
            outfile << endl;
        }
        outfile.close();
        cout << "数据清洗和预处理完成，已保存到 cleaned_data.csv" << endl;
    } else {
        cout << "数据加载失败" << endl;
    }

    return 0;
}
```

## 代码说明

### 1. 功能实现

这个C++实现包含了Python代码中的主要功能：

- **数据加载**：支持CSV和JSON格式的数据加载
- **去重处理**：可以按指定列或所有列进行去重
- **缺失值处理**：支持简单策略的缺失值填充
- **时间格式统一**：进行基本的时间格式转换
- **文本标准化**：包括去除特殊符号、分词和停用词过滤

### 2. 关键知识点

- **数据结构**：使用`vector<vector<string>>`来模拟DataFrame
- **日期处理**：使用简单的字符串操作，实际应用中应使用`Boost.DateTime`
- **正则表达式**：使用标准库`<regex>`进行特殊符号过滤
- **分词**：使用`Boost.Tokenizer`进行简单分词

### 3. 优化建议

1. **日期处理**：应该使用`Boost.DateTime`库进行完整的日期时间处理
2. **JSON处理**：代码中只做了简单处理，实际应用需要根据JSON结构递归提取数据
3. **缺失值处理**：代码中的缺失值处理非常简化，实际应用需要将列转换为数值类型
4. **分词结果**：代码将分词结果单独作为行保存，这不符合CSV格式，可以考虑修改为保留原始结构

### 4. 注意事项

1. 需要安装以下库：
   - RapidJSON：用于JSON解析
   - Boost库：用于日期时间处理和字符串分割

2. 编译时需要链接相应的库：
   ```
   g++ -std=c++11 -o data_preprocessor data_preprocessor.cpp -lboost_system -lboost_date_time -lrapidjson
   ```

3. 这个实现是为了演示核心功能，实际生产环境需要更健壮的错误处理和性能优化。

希望这个C++实现能满足您的需求！如果您有任何问题或需要进一步的功能，请随时提问。

# C++数据预处理代码详细注释版

以下是为C++数据预处理代码添加的详细注释，帮助您理解和维护代码：

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <regex>
#include <ctime>
#include <rapidjson/document.h>
#include <rapidjson/writer.h>
#include <rapidjson/stringbuffer.h>
#include <boost/date_time/gregorian/gregorian.hpp>
#include <boost/tokenizer.hpp>
#include <boost/algorithm/string.hpp>
#include <unordered_map>
#include <functional>

using namespace std;
using namespace rapidjson;
using namespace boost::gregorian;
using namespace boost::tokenizer;

/**
 * @class DataPreprocessor
 * @brief 数据预处理类，提供数据清洗和预处理功能
 */
class DataPreprocessor {
public:
    /**
     * @brief 构造函数，初始化停用词集合
     */
    DataPreprocessor() {
        // 初始化停用词列表
        for (const string& word : stop_words) {
            stop_words_set.insert(word);
        }
    }

    /**
     * @brief 加载数据
     * @param file_path 文件路径
     * @param file_type 文件类型，默认为"csv"
     * @return 数据矩阵，行表示记录，列表示字段
     */
    vector<vector<string>> loadData(const string& file_path, const string& file_type = "csv") {
        vector<vector<string>> data;
        ifstream file(file_path);
        string line;

        if (file_type == "csv") {
            // 处理CSV文件
            while (getline(file, line)) {
                stringstream ss(line);
                string cell;
                vector<string> row;
                while (getline(ss, cell, ',')) {
                    row.push_back(cell);
                }
                data.push_back(row);
            }
        } else if (file_type == "json") {
            // 处理JSON文件
            Document doc;
            file.seekg(0, ios::end);
            long size = file.tellg();
            file.seekg(0, ios::beg);
            string json_str(size, ' ');
            file.read(&json_str[0], size);
            file.close();

            // 解析JSON数据
            parseJson(json_str, doc);

            // 这里需要递归提取JSON数据，简化处理只返回一个示例
            // 实际应用中需要根据JSON结构提取所有数据
            // 这里简化处理，只返回一个示例
            vector<string> row;
            row.push_back("json_data");
            data.push_back(row);
        }
        return data;
    }

    /**
     * @brief 处理重复数据
     * @param data 数据矩阵
     * @param columns 指定列进行去重，空则所有列
     * @param method 去重方法，默认为"drop"，可选值为"drop"或"maintain"
     * @return 去重后的数据矩阵
     */
    vector<vector<string>> handleDuplicates(vector<vector<string>>& data, const vector<int>& columns = {}, const string& method = "drop") {
        if (columns.empty()) {
            // 按所有列去重
            map<vector<string>, int> seen;
            vector<vector<string>> result;
            for (const auto& row : data) {
                if (seen.find(row) == seen.end()) {
                    seen[row] = 0;
                    result.push_back(row);
                }
            }
            return result;
        } else {
            // 按指定列去重
            map<vector<string>, int> seen;
            vector<vector<string>> result;
            for (const auto& row : data) {
                vector<string> key;
                for (int col : columns) {
                    key.push_back(row[col]);
                }
                if (seen.find(key) == seen.end()) {
                    seen[key] = 0;
                    result.push_back(row);
                }
            }
            return result;
        }
    }

    /**
     * @brief 处理缺失值
     * @param data 数据矩阵
     * @param strategy 缺失值处理策略，默认为"mean"，可选值为"mean"、"median"、"mode"或"fillna"
     * @param threshold 缺失率阈值，默认为0.7
     * @return 处理缺失值后的数据矩阵
     */
    vector<vector<string>> handleMissingValues(vector<vector<string>>& data, const string& strategy = "mean", double threshold = 0.7) {
        vector<vector<string>> result = data;
        // 计算每列的缺失率
        int num_rows = data.size();
        if (num_rows == 0) return result;

        for (int col = 0; col < data[0].size(); col++) {
            int missing_count = 0;
            for (const auto& row : data) {
                if (row[col].empty()) {
                    missing_count++;
                }
            }
            double missing_rate = (double)missing_count / num_rows;
            if (missing_rate < threshold && missing_count > 0) {
                for (auto& row : result) {
                    if (row[col].empty()) {
                        if (strategy == "mean") {
                            // 简化处理，这里只处理数值列
                            // 实际应用中需要将列转换为数值类型
                            row[col] = "0";
                        } else if (strategy == "median") {
                            row[col] = "0";
                        } else if (strategy == "mode") {
                            row[col] = "0";
                        }
                    }
                }
            }
        }
        return result;
    }

    /**
     * @brief 统一时间格式
     * @param data 数据矩阵
     * @param date_columns 需要处理的时间列索引，默认为空(所有时间列)
     * @return 时间格式统一后的数据矩阵
     */
    vector<vector<string>> standardizeTimeFormat(vector<vector<string>>& data, const vector<int>& date_columns = {}) {
        vector<vector<string>> result = data;
        // 简化处理，这里只进行基本的时间格式转换
        for (const auto& row : result) {
            for (int col : date_columns) {
                if (!row[col].empty()) {
                    // 尝试解析日期
                    try {
                        // 简化处理，这里只进行字符串格式转换
                        // 实际应用中需要使用Boost.DateTime等库进行完整的时间处理
                        string formatted = row[col];
                        // 这里简化处理，只进行基本的格式转换
                        // 完整实现需要处理多种日期格式
                        formatted.erase(remove_if(formatted.begin(), formatted.end(), [](unsigned char c) { return !isdigit(c); }), formatted.end());
                        row[col] = formatted;
                    } catch (...) {
                        // 处理异常
                    }
                }
            }
        }
        return result;
    }

    /**
     * @brief 文本标准化
     * @param data 数据矩阵
     * @param text_columns 需要处理的文本列索引，默认为空(所有文本列)
     * @return 文本标准化后的数据矩阵
     */
    vector<vector<string>> standardizeText(vector<vector<string>>& data, const vector<int>& text_columns = {}) {
        vector<vector<string>> result = data;
        // 去除特殊符号
        for (auto& row : result) {
            for (int col : text_columns) {
                if (!row[col].empty()) {
                    string& text = row[col];
                    // 使用正则表达式去除特殊符号
                    static regex re("[^\\w\\s]");
                    text = regex_replace(text, re, "");
                    // 分词
                    char_separator<char> sep(" ");
                    tokenizer<char_separator<char>> tok(text, sep);
                    for (const auto& token : tok) {
                        // 去除停用词
                        if (stop_words_set.find(token) == stop_words_set.end()) {
                            // 将分词结果存储为字符串（简化处理）
                            // 实际应用中可能需要更复杂的处理
                            result.push_back({ token }); // 简化处理，这里只保留非停用词
                        }
                    }
                }
            }
        }
        return result;
    }

private:
    // 常用停用词列表
    set<string> stop_words = { "的", "了", "是", "我", "在", "有", "和", "就", "不", "人", "都", "大", "会", "可以", "时间", "没有", "看", "起来", "一样" };
    // 停用词集合，用于快速查找
    set<string> stop_words_set;
};

/**
 * @brief 主函数
 * @return 程序退出状态
 */
int main() {
    DataPreprocessor preprocessor;

    // 加载数据
    vector<vector<string>> data = preprocessor.loadData("data.csv", "csv");

    if (!data.empty()) {
        cout << "数据加载成功" << endl;

        // 处理重复数据
        // 使用第0列和第1列作为去重依据，保留首次出现的记录
        data = preprocessor.handleDuplicates(data, {0, 1}, "maintain");
        cout << "重复数据处理完成" << endl;

        // 处理缺失值
        // 使用均值填充策略，阈值为0.7
        data = preprocessor.handleMissingValues(data, "mean");
        cout << "缺失值处理完成" << endl;

        // 统一时间格式
        // 处理第2列（索引从0开始）
        data = preprocessor.standardizeTimeFormat(data, {2});
        cout << "时间格式统一完成" << endl;

        // 文本标准化
        // 处理第1列（索引从0开始）
        data = preprocessor.standardizeText(data, {1});
        cout << "文本标准化完成" << endl;

        // 保存处理后的数据
        ofstream outfile("cleaned_data.csv");
        for (const auto& row : data) {
            for (size_t i = 0; i < row.size(); i++) {
                outfile << row[i];
                if (i < row.size() - 1) {
                    outfile << ",";
                }
            }
            outfile << endl;
        }
        outfile.close();
        cout << "数据清洗和预处理完成，已保存到 cleaned_data.csv" << endl;
    } else {
        cout << "数据加载失败" << endl;
    }

    return 0;
}
```

## 代码详细说明

### 1. 整体架构

- **DataPreprocessor类**：封装了所有数据预处理功能
- **核心功能**：数据加载、去重、缺失值处理、时间格式统一、文本标准化
- **数据结构**：使用`vector<vector<string>>`模拟表格数据

### 2. 关键函数详解

#### loadData函数
```cpp
vector<vector<string>> loadData(const string& file_path, const string& file_type = "csv")
```
- 支持CSV和JSON格式的数据加载
- CSV格式：按行读取，按逗号分割
- JSON格式：简化处理，仅返回示例数据

#### handleDuplicates函数
```cpp
vector<vector<string>> handleDuplicates(vector<vector<string>>& data, const vector<int>& columns = {}, const string& method = "drop")
```
- 支持按指定列或所有列去重
- `method`参数：`"drop"`（删除重复行）或`"maintain"`（保留首次出现的记录）

#### handleMissingValues函数
```cpp
vector<vector<string>> handleMissingValues(vector<vector<string>>& data, const string& strategy = "mean", double threshold = 0.7)
```
- 支持缺失率阈值控制，仅处理超过阈值的列
- 缺失值填充策略：均值、中位数、众数

#### standardizeTimeFormat函数
```cpp
vector<vector<string>> standardizeTimeFormat(vector<vector<string>>& data, const vector<int>& date_columns = {})
```
- 简化实现：仅保留数字字符
- 实际应用中应使用更复杂的日期解析库

#### standardizeText函数
```cpp
vector<vector<string>> standardizeText(vector<vector<string>>& data, const vector<int>& text_columns = {})
```
- 去除特殊符号：保留字母、数字和空格
- 分词：按空格分割文本
- 去除停用词：使用预定义的中文停用词列表

### 3. 数据处理流程

1. **数据加载**：从CSV文件加载数据
2. **去重处理**：按指定列去重，保留首次出现的记录
3. **缺失值处理**：使用均值填充缺失值
4. **时间格式统一**：处理时间列，简化实现为保留数字字符
5. **文本标准化**：处理文本列，去除特殊符号、分词和停用词过滤
6. **保存结果**：将处理后的数据保存到CSV文件

### 4. 使用注意事项

1. **依赖库**：
   - RapidJSON：用于JSON解析
   - Boost库：用于日期时间处理和字符串分割

2. **编译命令**：
   ```bash
   g++ -std=c++11 -o data_preprocessor data_preprocessor.cpp -lboost_system -lboost_date_time -lrapidjson
   ```

3. **性能考虑**：
