class DatabaseConnector {
private:
    std::string host;
    std::string user;
    std::string password;
    std::string dbname;
    std::string port;

public:
    DatabaseConnector(const std::string& config) {
        // JSON形式の設定文字列を解析
        std::istringstream iss(config);
        std::string key, value;
        while (getline(iss, key, ',')) {
            size_t pos = key.find('=');
            if (pos != std::string::npos) {
                std::string cleanKey = key.substr(0, pos);
                std::string cleanValue = key.substr(pos + 1);
                if (cleanKey == "host") host = cleanValue;
                else if (cleanKey == "user") user = cleanValue;
                else if (cleanKey == "password") password = cleanValue;
                else if (cleanKey == "dbname") dbname = cleanValue;
                else if (cleanKey == "port") port = cleanValue;
            }
        }
    }

    void connect() {
        std::cout << "データベースに接続しています..." << std::endl;
        // 実際のデータベース接続処理をここに実装
    }

    void executeQuery(const std::string& query) {
        std::cout << "クエリを実行しています: " << query << std::endl;
        // 実際のクエリ実行処理をここに実装
    }
};

// ファイル処理ユーティリティ
class FileUtils {
public:
    static std::vector<std::string> readFile(const std::string& filePath) {
        std::ifstream file(filePath);
        if (!file.is_open()) {
            throw std::runtime_error("ファイルを開けません: " + filePath);
        }

        std::vector<std::string> lines;
        std::string line;
        while (std::getline(file, line)) {
            lines.push_back(line);
        }
        return lines;
    }

    static void writeFile(const std::string& filePath, const std::vector<std::string>& content) {
        std::ofstream file(filePath);
        if (!file.is_open()) {
            throw std::runtime_error("ファイルを書き出せません: " + filePath);
        }

        for (const auto& line : content) {
            file << line << std::endl;
        }
    }

    static void saveCSV(const std::vector<std::vector<std::string>>& data, const std::string& filePath) {
        std::ofstream file(filePath);
        if (!file.is_open()) {
            throw std::runtime_error("CSVファイルを書き出せません: " + filePath);
        }

        for (const auto& row : data) {
            for (size_t i = 0; i < row.size(); ++i) {
                file << row[i];
                if (i < row.size() - 1) file << ",";
            }
            file << "\n";
        }
    }
};

